/* GENERATED by gen_chunksim.py -- do not edit. See that file for why the
 * controller is LIFTED from cofq_flush rather than reimplemented here. */
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>

#ifndef COF_LAUNCH_TARGET_MS
#define COF_LAUNCH_TARGET_MS  1000.0f
#endif
#ifndef COF_CHUNK_HARD_FLOOR
#define COF_CHUNK_HARD_FLOOR  1024u
#endif
#define COF_CHUNK_TARGET_MS   250.0f
#define COF_FLUSH_CK(x) do { (void)(x); } while (0)
#define COFAC_THREADS_MAX 256

typedef struct {
    /* Both spellings: the current controller calls it eff_prev_valve (the
     * SLICE), the pre-fix one called it chunk_prev_valve (the chunk). Carrying
     * both lets the same harness compile either revision, which is what makes
     * a genuine control possible. */
    uint32_t chunk_cur, chunk_ceiling, eff_prev_valve, chunk_prev_valve, cap;
    float    ms_prev_valve;
    int      valve_parked;
} cofq_t;
typedef struct { uint32_t chunk; } sim_set_t;

static uint32_t cof_chunk_floor(int blocks, int threads)
{
    if (threads > COFAC_THREADS_MAX) threads = COFAC_THREADS_MAX;
    const uint64_t f = (uint64_t)(blocks > 0 ? blocks : 1)
                     * (uint64_t)(threads > 0 ? threads : 1);
    return f > 0xffffffffull ? 0xffffffffu : (uint32_t)f;
}

static int g_reports;
static uint32_t g_last_report;
static void cof_report_chunk(uint32_t c, uint32_t n, int pinned)
{ (void)pinned; g_reports++; g_last_report = c < n ? c : n; }

static int g_quiet = 1;
#define fprintf sim_fprintf
static int sim_fprintf(FILE *f, const char *fmt, ...) { (void)f; (void)fmt; return 0; }

/* ---------------- the lifted controller ---------------- */
static void controller(cofq_t *Q, uint32_t n, float sim_launch_ms,
                       float t0, float t1, uint32_t chunk,
                       int blocks, int threads)
{
    sim_set_t S; S.chunk = Q->chunk_cur;
    int valve_acted = 0;
    struct { int fired; } pk0, pk1; pk0.fired = 1; pk1.fired = 0;
    (void)pk0; (void)pk1; (void)valve_acted; (void)S;
    /* ---- the safety valve: an over-bound LAUNCH may descend past the floor -
     *
     * Ahead of the ordinary steering below, and independent of it: this is the
     * only path that may go below cof_chunk_floor(), and it fires only on a
     * measured launch that actually exceeded the bound. On hardware that never
     * does, nothing here executes and the behaviour is bit-for-bit what it was.
     */
    if (!chunk && !Q->valve_parked) {
        const float launch_ms = sim_launch_ms;
        if (launch_ms > COF_LAUNCH_TARGET_MS) {
            /* The slice this launch actually ran; see both uses below. */
            const uint32_t eff = Q->chunk_cur < n ? Q->chunk_cur : n;
            /* Proportional, at 0.8x the bound: from a large overshoot this
             * lands in one flush where halving needs several, and every flush
             * spent descending is a flush run at a size already known to be
             * dangerous.
             *
             * SCALED FROM THE SLICE THAT RAN, NOT FROM chunk_cur. cf_run_rounds
             * launches min(chunk, n) records, so launch_ms is the cost of `eff`
             * records and `eff` is what the ratio applies to. Scaling chunk_cur
             * instead divides the wrong quantity whenever the two differ --
             * which is not exotic: cof_chunk_floor() exceeds CQ_FLUSH on any
             * card with 86 or more SMs (a 4090's 196,608 against 131,072), so
             * the opening chunk is ALWAYS larger than n there. A 1100 ms
             * launch then descended 196,608 -> 142,987, still above n, leaving
             * the slice and the launch completely unchanged; from `eff` it
             * descends 131,072 -> 95,325 and bites on the first firing. */
            const double want = (double)eff
                              * ((double)COF_LAUNCH_TARGET_MS * 0.8)
                              / (double)launch_ms;
            uint32_t next = want < (double)COF_CHUNK_HARD_FLOOR
                          ? COF_CHUNK_HARD_FLOOR : (uint32_t)want;
            if (next >= Q->chunk_cur) next = Q->chunk_cur / 2;   /* always move */
            if (next < COF_CHUNK_HARD_FLOOR) next = COF_CHUNK_HARD_FLOOR;
            /* THE VALVE NEVER RAISES. The clamp above is what makes this
             * necessary: where cof_chunk_floor() is itself below
             * COF_CHUNK_HARD_FLOOR -- `--blocks 1 --threads 256` gives 256 --
             * the chunk opens at 256, the clamp lifts `next` to 1024, and the
             * valve would enlarge the launch it is trying to shorten, print it
             * as a descent, and then oscillate against the steering's floor.
             * Clamped here rather than by reordering the two lines above,
             * because HARD_FLOOR must still stop a descent going below it. */
            if (next > Q->chunk_cur) next = Q->chunk_cur;
            /* IS THE BOUND REACHABLE AT ALL? See eff_prev_valve. Two
             * measurements at genuinely different SLICE sizes give the affine
             * response 8h documents: a serial ECM-chain floor plus a
             * per-record term. Extrapolate the serial floor; if that alone is
             * over the bound, no chunk size can meet it and subdividing
             * further only multiplies per-launch overhead.
             *
             * PARKS IN PLACE. It never restores a larger chunk -- the reduction
             * already achieved is the safest launch this device has been shown
             * to run, and giving it back trades a launch that survives the
             * watchdog for one that may not. That also makes a park triggered
             * by a noisy measurement conservative rather than dangerous. */
            int unreachable = 0;
            if (Q->eff_prev_valve > eff && Q->ms_prev_valve > 0.0f) {
                if (launch_ms >= Q->ms_prev_valve) {
                    unreachable = 1;      /* smaller slice, no faster at all */
                } else {
                    const double slope = (double)(Q->ms_prev_valve - launch_ms)
                                       / (double)(Q->eff_prev_valve - eff);
                    const double serial = (double)launch_ms
                                        - slope * (double)eff;
                    if (serial >= (double)COF_LAUNCH_TARGET_MS) unreachable = 1;
                }
            }
            if (unreachable) {
                fprintf(stderr,
                        "  cofactor: %u -> %u records/launch moved"
                        " %.0f -> %.0f ms, so the launch is not chunk-bound"
                        " and no slice can meet the %.0f ms bound; parking"
                        " here at %u records/launch\n",
                        Q->eff_prev_valve, eff,
                        (double)Q->ms_prev_valve, (double)launch_ms,
                        (double)COF_LAUNCH_TARGET_MS, Q->chunk_cur);
                Q->valve_parked = 1;
                valve_acted = 1;
            } else if (next != Q->chunk_cur) {
                fprintf(stderr,
                        "  cofactor: kernel launch %.0f ms is over this build's"
                        " %.0f ms bound; %u -> %u records/launch\n",
                        (double)launch_ms, (double)COF_LAUNCH_TARGET_MS,
                        Q->chunk_cur, next);
                /* Recorded BEFORE the assignment, for the guard above, and
                 * as the SLICE that ran rather than the chunk that named it. */
                Q->eff_prev_valve = eff;
                Q->ms_prev_valve = launch_ms;
                Q->chunk_cur = next;
                S.chunk = Q->chunk_cur;
                /* Sticky, so the steering's floor cannot pull it back up. */
                Q->chunk_ceiling = next;
                valve_acted = 1;
            } else {
                /* ALREADY AT COF_CHUNK_HARD_FLOOR AND STILL OVER THE BOUND.
                 * next == chunk_cur, so there is nothing left to subdivide --
                 * and because the branch above is what advances the guard's
                 * reference, without this the valve would re-measure the same
                 * floor every flush, print nothing and never conclude
                 * anything.
                 *
                 * PARKS HERE, NOT AT THE SIZE IT CAME FROM, and that is the
                 * difference from the no-progress branch above. The descent
                 * did shorten the launch -- measured on an RTX 3090 at a
                 * 200 ms bound, 6865 ms at the floor against 25449 ms at one
                 * grid -- it simply cannot reach the bound. Handing the
                 * throughput back would be trading a launch that survives the
                 * WATCHDOG for one that does not: the bound carries 2x margin
                 * on the TDR it is derived from, so over the bound is not over
                 * the watchdog, and over the bound by 2.4x is. Restoring is
                 * only safe when the shorter launch bought nothing, which is
                 * exactly the branch above. */
                fprintf(stderr,
                        "  cofactor: %u records/launch is the floor and the"
                        " launch is still %.0f ms, so no chunk size can meet"
                        " the %.0f ms bound; parking here rather than giving"
                        " the reduction back\n",
                        Q->chunk_cur, (double)launch_ms,
                        (double)COF_LAUNCH_TARGET_MS);
                Q->valve_parked = 1;
                valve_acted = 1;
            }
        } else if (Q->eff_prev_valve) {
            /* UNDER THE BOUND, SO THE HISTORY IS SPENT. The guard above
             * compares this launch against the one that provoked the last
             * descent, and the valve only speaks when it is over the bound --
             * so without this the reference could be fifty flushes old. A
             * machine that merely got slower later would then satisfy
             * `within 10% of the old measurement at a smaller chunk`, be read
             * as "descending does not help", and have the LARGER chunk
             * restored: a longer launch, concluded from two measurements taken
             * under different conditions. Resetting here means the guard only
             * ever compares consecutive over-bound flushes. */
            Q->eff_prev_valve = 0;
            Q->ms_prev_valve = 0.0f;
        }
    }

    /* Steer the NEXT flush. Only in auto mode, and only ever between flushes,
     * so the slice is fixed for the whole of the one just measured.
     *
     * Halving on an overrun and doubling on a large margin (rather than
     * scaling by the ratio) keeps this from chasing a single noisy flush; a
     * band runs many of them. The floor is the real protection -- a device slow
     * enough to stay over budget simply parks there, which is the free point
     * for it, and a device fast enough grows to one slice and stops. */
    if (!chunk && !valve_acted) {
        uint32_t floor_ch = cof_chunk_floor(blocks, threads);
        const uint32_t was = Q->chunk_cur;
#ifndef COF_CHUNK_NO_CEILING
        /* A measured over-bound launch has already proved that a full grid of
         * records does not fit this device's watchdog, so the floor -- which
         * is one record per thread and nothing more -- stops being a lower
         * limit. Without this the clamp below restores the rejected size on
         * the very next flush. COF_CHUNK_NO_CEILING is chunkcheck.sh's
         * control build; it must fail the gate. */
        if (Q->chunk_ceiling && floor_ch > Q->chunk_ceiling)
            floor_ch = Q->chunk_ceiling;
#endif
        const float stage = t0 + t1;
        if (stage > COF_CHUNK_TARGET_MS) {
            const uint32_t half = Q->chunk_cur / 2;
            Q->chunk_cur = (half > floor_ch) ? half : floor_ch;
        } else if (stage < COF_CHUNK_TARGET_MS / 4.0f && Q->chunk_cur < Q->cap) {
            /* Capped at the QUEUE CAPACITY, not at this flush's n. Several of
             * pipeline.cuh's cofq_flush call sites are checkpoint- or
             * stop-driven, so a band's first flush can be far smaller than a
             * full one; capping at that n would store the small value and then
             * need one flush per doubling to climb back, running the full
             * flushes in between at a slice far below the grid width -- the
             * +50.7% (32768) to +150.7% (16384) regime measured on the 3090.
             * That is the same trap the opening value above is unclamped to
             * avoid. cap is the real ceiling: n <= Q->cap always, and a stored
             * value above n costs nothing because cf_run_rounds treats any
             * chunk >= n as the single-slice case. */
            Q->chunk_cur = (Q->chunk_cur > Q->cap / 2) ? Q->cap
                                                       : Q->chunk_cur * 2;
            /* REACHABLE, BUT ONLY ON A SMALL FLUSH -- an earlier version of
             * this comment claimed outright that it cannot run here. `stage`
             * is t0+t1 over a whole side, which for a full CQ_FLUSH is tens of
             * times the 62.5 ms threshold, but pipeline.cuh's checkpoint- and
             * stop-driven call sites flush a few thousand records, where t0+t1
             * genuinely falls under it. So growth does run occasionally, and
             * being unclamped it is the one path that can lift chunk_cur back
             * over a ceiling set from an inflated measurement -- an accidental
             * relief valve, not a designed one, and it cannot be relied on.
             *
             * NOT clamped by chunk_ceiling, and that is deliberate.
             *
             * The ceiling exists to stop the FLOOR restoring a size a measured
             * launch has rejected; capping growth with it as well is a
             * different thing, and on a port whose steering is a real
             * measurement it is harmful. The interactivity watchdog is
             * contention-dependent (9z-p), so one busy moment sets a ceiling
             * from an inflated launch -- an M1 at 36864 records measuring
             * 1200 ms sets 24576 -- and the process could then never climb
             * back once the machine went idle, though every later measurement
             * said it should. A measurement-driven controller does not need
             * protecting from growth: if it grows too far, the next launch is
             * over the bound and it descends again, which is the loop working.
             *
             * This branch is in any case unreachable here, where `stage` is a
             * whole side's sum and never falls below a quarter of the target.
             * It was clamped for the Metal port's benefit, where it IS live --
             * which is exactly where the cap does the damage. */
        }
        if (Q->chunk_cur != was) cof_report_chunk(Q->chunk_cur, n, 0);
    }

}
#undef fprintf

/* ---------------- device models ---------------- */
/* launch(eff) for a slice of `eff` records, in ms. */
struct Model {
    const char *name;
    double a;      /* serial floor: one ECM chain, independent of the slice */
    double b;      /* per-record term */
    double wave;   /* records per wave; below it the launch is flat (a chain) */
};
static double model_launch(const Model &m, uint32_t eff)
{
    double e = (double)eff;
    if (m.wave > 0 && e < m.wave) e = m.wave;   /* cannot go below one chain */
    return m.a + m.b * e;
}

static int g_fail, g_checks;
/* Announces BOTH ways. A check that prints only on failure is
 * indistinguishable from a check that never executed, which is how a gate ends
 * up passing vacuously -- the failure this tree has hit repeatedly. Repeated
 * checks inside a loop are counted and summarised by the caller instead. */
static void ck(int ok, const char *what, const char *detail)
{
    g_checks++;
    if (!ok) { printf("FAIL   %-46s %s\n", what, detail ? detail : ""); g_fail = 1; }
}
static void ck1(int ok, const char *what, const char *detail)
{
    g_checks++;
    if (ok) printf("PASS   %-46s %s\n", what, detail ? detail : "");
    else  { printf("FAIL   %-46s %s\n", what, detail ? detail : ""); g_fail = 1; }
}

int main(void)
{
    /* ---- 1. ARITHMETIC SAFETY: fuzz every reachable input combination ---- */
    {
        static const uint32_t chunks[] = {1u, 2u, 1023u, 1024u, 1025u, 4096u,
            33792u, 104448u, 125952u, 131072u, 196608u, 524288u, 0x7fffffffu};
        static const uint32_t ns[] = {1u, 2u, 1890u, 65536u, 130529u, 131072u};
        static const float mss[] = {1000.001f, 1001.f, 1100.f, 2400.f, 13120.f,
            25449.f, 1e6f, 1e9f};
        static const uint32_t prevs[] = {0u, 1u, 1024u, 131072u, 0xffffffffu};
        static const float pms[] = {0.f, 1.f, 1000.f, 1e9f};
        long cases = 0;
        for (size_t a = 0; a < sizeof chunks / sizeof *chunks; a++)
        for (size_t b = 0; b < sizeof ns / sizeof *ns; b++)
        for (size_t c = 0; c < sizeof mss / sizeof *mss; c++)
        for (size_t d = 0; d < sizeof prevs / sizeof *prevs; d++)
        for (size_t e = 0; e < sizeof pms / sizeof *pms; e++) {
            cofq_t Q; memset(&Q, 0, sizeof Q);
            Q.chunk_cur = chunks[a]; Q.cap = 131072u;
            Q.eff_prev_valve = prevs[d]; Q.ms_prev_valve = pms[e];
            const uint32_t before = Q.chunk_cur;
            controller(&Q, ns[b], mss[c], 5000.f, 5000.f, 0u, 492, 256);
            cases++;
            char det[160];
            snprintf(det, sizeof det, "chunk %u n %u ms %g prev %u/%g -> %u",
                     before, ns[b], (double)mss[c], prevs[d], (double)pms[e],
                     Q.chunk_cur);
            ck(Q.chunk_cur >= 1u, "chunk never becomes zero", det);
            ck(Q.chunk_cur <= before, "the valve never raises the chunk", det);
            ck(!(Q.chunk_ceiling && Q.chunk_ceiling > before),
               "the ceiling never exceeds the chunk it came from", det);
            ck(std::isfinite((double)Q.ms_prev_valve), "ms_prev_valve stays finite", det);
        }
        printf("PASS   %-46s %ld cases\n", "arithmetic safety, exhaustive grid", cases);
    }

    /* ---- 2. INVARIANTS over full trajectories, every device model ---- */
    {
        static const Model models[] = {
          {"proportional, meets bound",      0.0,   0.0000200, 0},
          {"proportional, far over",         0.0,   0.0002000, 0},
          {"affine, serial 950 (reachable)", 950.0, 0.0023820, 0},
          {"affine, serial 1050 (unreach.)", 1050.0,0.0023820, 0},
          {"step: one ECM chain, flat",      2400.0,0.0000001, 1e9},
          {"wave floor at 2k records",       90.0,  0.0100000, 2000},
          {"980 Ti class, 2500 at floor",    400.0, 0.0621000, 0},
        };
        static const int blocks[] = {132, 492, 768, 2048};   /* 22, 82, 128, 341 SMs */
        for (size_t m = 0; m < sizeof models / sizeof *models; m++)
        for (size_t g = 0; g < sizeof blocks / sizeof *blocks; g++) {
            cofq_t Q; memset(&Q, 0, sizeof Q);
            Q.cap = 131072u;
            Q.chunk_cur = cof_chunk_floor(blocks[g], 256);
            const uint32_t n = 130529u;
            uint32_t seen_ceiling = 0; int spoken = 0; uint32_t after_spoke = 0;
            int parked_then_moved = 0, rose_after_speak = 0, ceil_rose = 0;
            for (int flush = 0; flush < 60; flush++) {
                const uint32_t eff = Q.chunk_cur < n ? Q.chunk_cur : n;
                const double L = model_launch(models[m], eff);
                const uint32_t was = Q.chunk_cur;
                const int was_parked = Q.valve_parked;
                const uint32_t was_ceiling = Q.chunk_ceiling;
                controller(&Q, n, (float)L, 5000.f, 5000.f, 0u, blocks[g], 256);
                if (Q.chunk_ceiling && was_ceiling && Q.chunk_ceiling > was_ceiling)
                    ceil_rose = 1;
                if (Q.chunk_ceiling) seen_ceiling = Q.chunk_ceiling;
                if (L > COF_LAUNCH_TARGET_MS) spoken = 1;
                if (spoken) { if (Q.chunk_cur > after_spoke && after_spoke) rose_after_speak = 1;
                              after_spoke = Q.chunk_cur; }
                if (was_parked && Q.chunk_cur != was) parked_then_moved = 1;
            }
            char det[200];
            snprintf(det, sizeof det, "%s / floor %u", models[m].name,
                     cof_chunk_floor(blocks[g], 256));
            ck(!ceil_rose,          "the ceiling is monotone non-increasing", det);
            ck(!rose_after_speak,   "the chunk never rises once the valve spoke", det);
            ck(!parked_then_moved,  "a parked valve never moves the chunk again", det);
            ck(Q.chunk_cur >= 1u,   "trajectory never reaches a zero chunk", det);
            (void)seen_ceiling;
        }
        printf("PASS   %-46s %zu models x %zu grids\n", "trajectory invariants",
               sizeof models / sizeof *models, sizeof blocks / sizeof *blocks);
    }

    /* ---- 3. THE THREE VALVE BRANCHES ARE ALL REACHED ---- */
    {
        int saw_descent = 0, saw_unreach = 0, saw_floor = 0;
        /* descent + unreachable: a flat (chain-bound) response */
        { cofq_t Q; memset(&Q, 0, sizeof Q); Q.cap = 131072u;
          Q.chunk_cur = 125952u;
          const Model fm = {"flat", 2400.0, 0.0000001, 1e9};
          for (int f = 0; f < 10; f++) {
              const uint32_t eff = Q.chunk_cur < 130529u ? Q.chunk_cur : 130529u;
              const uint32_t was = Q.chunk_cur; const int wp = Q.valve_parked;
              controller(&Q, 130529u, (float)model_launch(fm, eff), 5000.f, 5000.f, 0u, 492, 256);
              if (Q.chunk_cur < was) saw_descent = 1;
              if (!wp && Q.valve_parked && Q.chunk_cur == was) saw_unreach = 1;
          } }
        /* floor park: hard floor above the grid floor, so next == chunk_cur */
        { cofq_t Q; memset(&Q, 0, sizeof Q); Q.cap = 131072u;
          Q.chunk_cur = cof_chunk_floor(492, 256);
          const uint32_t was = Q.chunk_cur;
          controller(&Q, 130529u, 1232.0f, 5000.f, 5000.f, 0u, 492, 256);
          if (Q.valve_parked && Q.chunk_cur == was && !Q.eff_prev_valve) saw_floor = 1;
        }
        /* Scoped: with COF_CHUNK_HARD_FLOOR above the starting chunk there is
         * nothing to descend TO -- every candidate clamps back to chunk_cur
         * and the floor park is the only reachable branch. Asserting a descent
         * there would be asserting something the build cannot do. */
        if (COF_CHUNK_HARD_FLOOR < 125952u) {
            ck1(saw_descent, "the descent branch is reached", 0);
            ck1(saw_unreach, "the unreachable park is reached", 0);
        } else {
            printf("SKIP   %-46s %s\n", "descent / unreachable park",
                   "(hard floor above the grid: nothing to descend to)");
        }
        if (COF_CHUNK_HARD_FLOOR >= 131072u)
            ck1(saw_floor, "the floor park is reached", "(hard floor above the grid)");
        else
            printf("SKIP   %-46s %s\n", "the floor park",
                   "build with -DCOF_CHUNK_HARD_FLOOR=200000u to reach it");
    }

    /* ---- 4. THE HISTORY RESET actually clears ---- */
    {
        cofq_t Q; memset(&Q, 0, sizeof Q); Q.cap = 131072u; Q.chunk_cur = 125952u;
        controller(&Q, 130529u, 2400.f, 5000.f, 5000.f, 0u, 492, 256);
        if (COF_CHUNK_HARD_FLOOR < 125952u) {
            ck1(Q.eff_prev_valve != 0u, "a descent records its slice", 0);
            controller(&Q, 130529u, 500.f, 5000.f, 5000.f, 0u, 492, 256);
            ck1(Q.eff_prev_valve == 0u && Q.ms_prev_valve == 0.0f,
               "an in-bound flush clears the history", 0);
        } else {
            printf("SKIP   %-46s %s\n", "history record / reset",
                   "(hard floor above the grid: no descent to record)");
        }
    }

    /* ---- 5. A HEALTHY CARD IS UNTOUCHED ---- */
    {
        cofq_t Q; memset(&Q, 0, sizeof Q); Q.cap = 131072u;
        Q.chunk_cur = cof_chunk_floor(492, 256);
        const uint32_t open = Q.chunk_cur;
        for (int f = 0; f < 200; f++)
            controller(&Q, 130529u, 240.f, 5000.f, 5000.f, 0u, 492, 256);
        ck1(Q.chunk_ceiling == 0u && Q.eff_prev_valve == 0u
           && Q.ms_prev_valve == 0.0f && Q.valve_parked == 0,
           "under the bound, all four new fields stay zero", 0);
        ck1(Q.chunk_cur == open, "and the chunk trajectory is the floor, as before", 0);
    }

    if (g_fail) { printf("CHUNK CONTROLLER SIM: FAIL (%d checks)\n", g_checks); return 1; }
    printf("CHUNK CONTROLLER SIM: PASS (%d checks)\n", g_checks);
    return 0;
}
